const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Rectangle([50, 25, 60, 30]); // Southern Iran
    const date1 = '2020-01-08';
    const date2 = '2020-01-13';

    // Helper function to get water extent count for a given date
    async function getWaterCount(date) {
      // Try Sentinel-1 first (radar, cloud-penetrating)
      let s1 = ee.ImageCollection('COPERNICUS/S1_GRD')
        .filterBounds(region)
        .filterDate(date, ee.Date(date).advance(1, 'day')) // exact date
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'));

      let count = s1.size().getInfo();
      let img = null;
      if (count > 0) {
        img = ee.Image(s1.first());
        // Water detection: low backscatter in VV and VH
        const water = img.select('VV').lt(-16).and(img.select('VH').lt(-22)).rename('water');
        const stats = water.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: 1000,
          maxPixels: 1e9,
        });
        const waterCount = stats.get('water').getInfo();
        return { count: waterCount, source: 'Sentinel-1', images: count };
      } else {
        // Fallback: try ±1 day window for Sentinel-1
        s1 = ee.ImageCollection('COPERNICUS/S1_GRD')
          .filterBounds(region)
          .filterDate(ee.Date(date).advance(-1, 'day'), ee.Date(date).advance(2, 'day'))
          .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
          .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'));
        count = s1.size().getInfo();
        if (count > 0) {
          img = ee.Image(s1.first());
          const water = img.select('VV').lt(-16).and(img.select('VH').lt(-22)).rename('water');
          const stats = water.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: region,
            scale: 1000,
            maxPixels: 1e9,
          });
          const waterCount = stats.get('water').getInfo();
          return { count: waterCount, source: 'Sentinel-1', images: count };
        } else {
          // Fallback to Sentinel-2 (optical) with cloud masking
          let s2 = ee.ImageCollection('COPERNICUS/S2_SR')
            .filterBounds(region)
            .filterDate(date, ee.Date(date).advance(1, 'day'))
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));
          count = s2.size().getInfo();
          if (count > 0) {
            img = ee.Image(s2.first());
            // Cloud masking using QA60
            const qa = img.select('QA60');
            const cloudBitMask = 1 << 10;
            const cirrusBitMask = 1 << 11;
            let mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
            img = img.updateMask(mask);
            // NDWI for water: (B3 - B8) / (B3 + B8) > 0.0
            const ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');
            const water = ndwi.gt(0.0).rename('water');
            const stats = water.reduceRegion({
              reducer: ee.Reducer.count(),
              geometry: region,
              scale: 1000,
              maxPixels: 1e9,
            });
            const waterCount = stats.get('water').getInfo();
            return { count: waterCount, source: 'Sentinel-2', images: count };
          } else {
            // Try wider date window for Sentinel-2 (±2 days)
            s2 = ee.ImageCollection('COPERNICUS/S2_SR')
              .filterBounds(region)
              .filterDate(ee.Date(date).advance(-2, 'day'), ee.Date(date).advance(3, 'day'))
              .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));
            count = s2.size().getInfo();
            if (count > 0) {
              img = ee.Image(s2.first());
              const qa = img.select('QA60');
              const cloudBitMask = 1 << 10;
              const cirrusBitMask = 1 << 11;
              let mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
              img = img.updateMask(mask);
              const ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');
              const water = ndwi.gt(0.0).rename('water');
              const stats = water.reduceRegion({
                reducer: ee.Reducer.count(),
                geometry: region,
                scale: 1000,
                maxPixels: 1e9,
              });
              const waterCount = stats.get('water').getInfo();
              return { count: waterCount, source: 'Sentinel-2', images: count };
            } else {
              return { count: null, source: 'None', images: 0 };
            }
          }
        }
      }
    }

    // Get water counts for both dates
    const result1 = await getWaterCount(date1);
    const result2 = await getWaterCount(date2);

    // Print intermediate stats
    console.log(`${date1}: ${result1.images} images (${result1.source}), Water pixels: ${result1.count}`);
    console.log(`${date2}: ${result2.images} images (${result2.source}), Water pixels: ${result2.count}`);

    // Check for no data
    if (result1.images === 0 || result2.images === 0) {
      console.log('<answer>C1</answer>');
      return;
    }

    // Check for valid pixel counts
    if (result1.count === null || result2.count === null) {
      // This means reducer returned null (no valid pixels in region)
      console.log('<answer>C2</answer>');
      return;
    }

    // Check for NaN or invalid numbers
    if (isNaN(result1.count) || isNaN(result2.count)) {
      console.log('<answer>C3</answer>');
      return;
    }

    // Compare
    if (result2.count > result1.count) {
      console.log('<answer>A</answer>');
    } else {
      console.log('<answer>B</answer>');
    }

  } catch (error) {
    console.error('Error:', error);
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
